// O Portão de Tarefas (RM-059, fatia F10). Na sessão de fase do GO, o quadro de tarefas do Claude Code é o do
// plano: a tarefa nativa só entra apontando uma tarefa do plano com `touch_paths` e verify que o núcleo confere
// (T10.1), só fecha com essa conferência aprovada (T10.2) e, com agent teams no piloto do núcleo, vai ao teammate
// ocioso quando a região dela está livre (T10.3). O Portão lê o núcleo pelo `$.ork` da ponte e pela ferramenta de
// leitura do plano, nunca o estado interno do disco; age só por comando do `ork`; nunca roda o verify por conta
// própria, nunca toma lease e nunca fala pelo dono. A lógica fica nos módulos puros ao lado; aqui só as chamadas ao
// `$`, sempre escritas como `x.noun.metodo(...)`, como o validador exige.
import type { EngineInterface, Register } from 'claude-code'
import type { PortaoQuadro, PortaoTarefa } from '../types'
import {
  argsDoPlano, decidirCriacao, escopoDoPlano, escopoDoRetrato, FERRAMENTA_DO_PLANO, IDADE_DO_PLANO_MS, IDADE_SEM_PLANO_MS,
  idsNoAssunto, jsonDoMcp, SERVIDOR, serveAoQuadro, tarefasDoPlano, textoDaRecusa, textoDoPlano, threadNoRetrato,
} from './plano'
import {
  argvDaConferencia, assinatura, contarRepeticao, lerConferencia, textoDeOutraConferencia, textoDoBloqueio, textoDoStatus,
  VIGIA_DA_CONFERENCIA_MS,
} from './verify'
import type { Leitura } from './verify'
import {
  escolherTarefa, nomeDoTeammate, paginaDosLeases, recusaDoTeammate, TETO_DE_PAGINAS_DE_LEASES, tetosDoAmbiente,
  textoDaEntrega, VIVOS,
} from './lease'
import type { LeaseAtivo } from './lease'

const QUADRO = { plugin: 'ork-portao', key: 'quadro' } as const

/**
 * O quadro desta carga do módulo (D9 do plano da thread): lido do `$.state` uma vez por thread e mudado só por
 * `mudarQuadro`, que aplica a mudança na versão mais nova sem esperar nada no meio e então grava sem versão. Um gancho
 * que espera uma chamada de `$` deixa outro gancho rodar: mudança feita sobre uma cópia lida antes apagaria a dele.
 */
let quadro: PortaoQuadro | null = null
/** O plano lido e quando, por thread; relido depois da idade (D3). */
let plano: { thread: string; em: number; tarefas: PortaoTarefa[] | null } | null = null
/**
 * A tarefa do plano que o Portão está conferindo no núcleo agora (D5): uma conferência por vez. Fica no módulo, não no
 * `$.state`: uma troca do worker mata o processo junto com a marca.
 */
let conferindo: string | null = null

/** A sessão de fase com thread, pelo contexto da ponte; qualquer outra sessão fica sem Portão (D1). */
type ContextoDeFase = { thread: string; raiz: string }
/**
 * A sessão em que o Portão age (D1): o contexto e as tarefas do plano, ou `null` nelas quando o plano não serve ao quadro
 * (ausente, sem tarefa que sirva ou com a leitura falhando). Sem elas, a criação e o teammate passam, mas a tarefa
 * registrada na criação continua conferida na conclusão: o núcleo lê o plano por conta própria.
 */
type Sessao = { ctx: ContextoDeFase; tarefas: PortaoTarefa[] | null }

const mensagem = (erro: unknown) => (erro instanceof Error ? erro.message : String(erro)).slice(0, 300)

function quadroVazio(thread: string): PortaoQuadro {
  return { thread, tarefas: {}, concluidas: [], repeticoes: {}, atribuicoes: {}, devolvidas: [], ultimaFalha: null }
}

async function contextoDeFase($: EngineInterface): Promise<ContextoDeFase | null> {
  const ctx = await $.ork.contexto()
  return ctx.papel === 'fase' && ctx.thread ? { thread: ctx.thread, raiz: ctx.raiz } : null
}

/** O quadro da thread: o do módulo, ou o do `$.state` na primeira leitura (a que chegar primeiro vale). */
async function lerQuadro($: EngineInterface, thread: string): Promise<PortaoQuadro> {
  if (quadro && quadro.thread === thread) return quadro
  const lido = (await $.state.get(QUADRO)).value
  if (quadro && quadro.thread === thread) return quadro
  quadro = lido && lido.thread === thread ? { ...quadroVazio(thread), ...lido } : quadroVazio(thread)
  return quadro
}

/**
 * Aplica `mudar` ao quadro mais novo, sem esperar nada entre ler e trocar, e grava (D9). `mudar` que devolve o mesmo
 * quadro não grava nada.
 */
async function mudarQuadro($: EngineInterface, thread: string, mudar: (q: PortaoQuadro) => PortaoQuadro): Promise<PortaoQuadro> {
  await lerQuadro($, thread)
  const atual = quadro as PortaoQuadro
  const novo = mudar(atual)
  if (novo === atual) return atual
  quadro = novo
  await $.state.set(QUADRO, novo)
  return novo
}

/** As tarefas do plano pela ferramenta de leitura do núcleo, com a idade da D3; erro sobe para quem chamou. */
async function lerTarefas($: EngineInterface, ctx: ContextoDeFase): Promise<PortaoTarefa[] | null> {
  const agora = await $.clock.now()
  if (plano && plano.thread === ctx.thread) {
    const idade = agora - plano.em
    const teto = plano.tarefas && plano.tarefas.length > 0 ? IDADE_DO_PLANO_MS : IDADE_SEM_PLANO_MS
    if (idade >= 0 && idade < teto) return plano.tarefas
  }
  const r = await $.mcp.call(SERVIDOR, FERRAMENTA_DO_PLANO, argsDoPlano(ctx.thread))
  const tarefas = tarefasDoPlano(textoDoPlano(jsonDoMcp(r, FERRAMENTA_DO_PLANO)))
  plano = { thread: ctx.thread, em: agora, tarefas }
  return tarefas
}

/**
 * A sessão em que o Portão age (D1): papel `fase` com thread, thread não fechada e GO no bloco pelo retrato da ponte. O
 * retrato que falha conta como GO e aberta, e fica na linha de status. As tarefas vêm do plano legível com ao menos uma
 * tarefa que serve ao quadro; sem ele, `null`.
 */
async function sessaoDoPortao($: EngineInterface): Promise<Sessao | null> {
  const ctx = await contextoDeFase($)
  if (!ctx) return null
  let retrato: { status: string | null; bloco: string | null } | null
  try {
    retrato = threadNoRetrato((await $.ork.retrato({ thread: ctx.thread })).retrato, ctx.thread)
  } catch {
    retrato = null
  }
  const doRetrato = escopoDoRetrato(retrato)
  if (!doRetrato.ativo) return null
  if (doRetrato.avisos.length > 0) $.ui.status(`portão: ${doRetrato.avisos.join('; ')}`)
  let tarefas: PortaoTarefa[] | null
  try {
    tarefas = await lerTarefas($, ctx)
  } catch (erro) {
    await anotarFalha($, 'leitura do plano', erro, ctx.thread)
    return { ctx, tarefas: null }
  }
  return { ctx, tarefas: escopoDoPlano(tarefas).ativo ? tarefas : null }
}

/**
 * Guarda a falha do próprio Portão no quadro e a diz uma vez no transcript (não vai ao modelo) e na linha de
 * status: nenhuma captura fica muda.
 */
async function anotarFalha($: EngineInterface, onde: string, erro: unknown, thread?: string): Promise<void> {
  const motivo = mensagem(erro)
  $.ui.status(`portão: falhou em ${onde}`)
  const alvo = thread ?? quadro?.thread
  if (!alvo) {
    $.ui.log(`Portão de Tarefas: falhou em ${onde}: ${motivo}`)
    return
  }
  const em = await $.clock.now()
  let nova = false
  await mudarQuadro($, alvo, q => {
    if (q.ultimaFalha?.onde === onde && q.ultimaFalha.motivo === motivo) return q
    nova = true
    return { ...q, ultimaFalha: { onde, motivo, em } }
  })
  if (nova) $.ui.log(`Portão de Tarefas: falhou em ${onde}: ${motivo}`)
}

/**
 * A tarefa do plano de uma tarefa nativa (D2): a registrada na criação vence (renomear não tira a tarefa do portão);
 * sem registro, o assunto que cita uma tarefa do plano que serve ao quadro, e uma só. Fora disso, a tarefa não é do
 * plano: a que o núcleo não confere nunca prende a conclusão.
 */
function tarefaDoEvento(assunto: unknown, taskId: string, q: PortaoQuadro, tarefas: readonly PortaoTarefa[]): string | null {
  const registrada = q.tarefas[taskId]
  if (registrada) return registrada
  const ids = idsNoAssunto(assunto).filter(id => tarefas.some(t => t.id === id && serveAoQuadro(t)))
  return ids.length === 1 ? (ids[0] as string) : null
}

/**
 * A conferência do verify da tarefa no núcleo (D4, D5): `ork claims conferir --tarefa` por `$.process.run`, na raiz
 * da sessão, com o vigia do mod. A espera é chamada de `$` e não conta no orçamento do gancho.
 */
async function rodarConferencia($: EngineInterface, ctx: ContextoDeFase, tarefa: string): Promise<Leitura> {
  try {
    const r = await $.process.run(argvDaConferencia(ctx.thread, tarefa), { cwd: ctx.raiz, timeoutMs: VIGIA_DA_CONFERENCIA_MS })
    return lerConferencia(tarefa, r.stdout, r.exitCode, r.stderr)
  } catch (erro) {
    return { tipo: 'indisponivel', motivo: `ork claims conferir não rodou: ${mensagem(erro)}` }
  }
}

/** Os tetos do piloto de agent teams que o núcleo passou no ambiente da sessão (D10); `null` sem eles. */
async function lerTetos($: EngineInterface): Promise<{ teammates: number; custoUsd: number } | null> {
  // O validador pede o nome literal; o teste do núcleo confere que ele é o de ENV_TEAMMATES e ENV_CUSTO.
  return tetosDoAmbiente(await $.env.get('ORK_AGENT_TEAMS_TEAMMATES'), await $.env.get('ORK_AGENT_TEAMS_CUSTO_USD'))
}

/** O custo da sessão como o `/cost` soma; `null` quando ele não vem. */
async function custoDaSessao($: EngineInterface): Promise<number | null> {
  const uso = await $.session.usage()
  return typeof uso.cost?.usd === 'number' ? uso.cost.usd : null
}

/**
 * Os leases ativos de todas as threads (D8 revista), página a página pelo `nextOffset`. O servidor MCP da sessão de fase
 * é fixado na thread e o retrato dele só traz os leases dela; por isso a leitura vai pela consulta `maestro` da lista
 * fechada da ponte (`ork maestro --json --section leases --offset N`), que vê o projeto inteiro. Lança se uma página não
 * vem ou se a leitura fica incompleta (lacuna de verdade, retrato em conflito, mais páginas que o teto): lista parcial
 * nunca vira região livre.
 */
async function lerLeases($: EngineInterface): Promise<LeaseAtivo[]> {
  const leases: LeaseAtivo[] = []
  let offset = 0
  for (let pagina = 0; pagina < TETO_DE_PAGINAS_DE_LEASES; pagina++) {
    const pedido = { consulta: 'maestro' as const, secao: 'leases' as const, offset }
    const p = paginaDosLeases(await $.ork.ler(pedido))
    if (p.lacuna) throw new Error(`ork-portao: ${p.lacuna}`)
    leases.push(...p.leases)
    if (p.proximo === null) return leases
    offset = p.proximo
  }
  throw new Error(`ork-portao: a seção leases tem mais de ${TETO_DE_PAGINAS_DE_LEASES} páginas; o resto não foi lido`)
}

export const register: Register = on => {
  // A criação (T10.1): a tarefa nativa só entra apontando uma tarefa do plano que serve ao quadro (D2, D3). A recusa
  // volta ao modelo pelo `block`, com o motivo e as tarefas que servem; a que passa fica registrada pelo id nativo.
  on('classic.TaskCreated', async ($, e, next) => {
    const sessao = await sessaoDoPortao($)
    if (!sessao || !sessao.tarefas) return next(e)
    const veredito = decidirCriacao(e.task_subject, sessao.tarefas)
    if (veredito.tipo === 'recusa') return { block: textoDaRecusa(veredito, e.task_subject, sessao.tarefas) }
    await mudarQuadro($, sessao.ctx.thread, q => ({ ...q, tarefas: { ...q.tarefas, [String(e.task_id)]: veredito.tarefa } }))
    return next(e)
  }).catch(async ($, e, next) => {
    // Na reentrada o gancho nem rodou e as chamadas de `$` recusam: só a falha de verdade é anotada.
    if (next.error && next.error.kind !== 're-entry') await anotarFalha($, 'criação de tarefa', next.error.message ?? next.error.kind)
    return next(e)
  })

  // A conclusão (T10.2): a tarefa do plano só fecha com a conferência do núcleo aprovada (D4), uma por vez (D5).
  // Todo bloqueio volta ao modelo com o motivo e a saída (corrigir, ou devolver a tarefa para pending), e a terceira
  // vez seguida com o mesmo resultado manda deixar a tarefa aberta (D6). Tarefa que não é do plano passa.
  on('classic.TaskCompleted', async ($, e, next) => {
    const sessao = await sessaoDoPortao($)
    if (!sessao) return next(e)
    const { ctx } = sessao
    const tarefa = tarefaDoEvento(e.task_subject, String(e.task_id), await lerQuadro($, ctx.thread), sessao.tarefas ?? [])
    if (!tarefa) return next(e)
    if (conferindo) return { block: textoDeOutraConferencia(tarefa, conferindo) }
    conferindo = tarefa
    let leitura: Leitura
    try {
      $.ui.status(`portão: conferindo ${tarefa} no núcleo`)
      leitura = await rodarConferencia($, ctx, tarefa)
    } finally {
      conferindo = null
    }
    if (leitura.tipo === 'aprovada') {
      const resultado = await next(e)
      if (!resultado.block) {
        await mudarQuadro($, ctx.thread, q => {
          const repeticoes = { ...q.repeticoes }
          delete repeticoes[tarefa]
          return { ...q, concluidas: q.concluidas.includes(tarefa) ? q.concluidas : [...q.concluidas, tarefa], repeticoes }
        })
      }
      $.ui.status(textoDoStatus(tarefa, leitura))
      return resultado
    }
    const marca = assinatura(leitura)
    let vezes = 1
    await mudarQuadro($, ctx.thread, q => {
      const repeticao = contarRepeticao(q.repeticoes[tarefa], marca)
      vezes = repeticao.vezes
      return { ...q, repeticoes: { ...q.repeticoes, [tarefa]: repeticao } }
    })
    $.ui.status(textoDoStatus(tarefa, leitura))
    return { block: textoDoBloqueio(tarefa, leitura, vezes) }
  }).catch(async ($, e, next) => {
    // A conclusão fecha só aprovada (D4): se o próprio Portão falhou no meio, a tarefa registrada, ou a que cita um id
    // de tarefa do plano no assunto, não fecha. A anotação é melhor esforço: o bloqueio não depende dela.
    if (!next.error || next.error.kind === 're-entry') return next(e)
    const motivo = next.error.message ?? next.error.kind
    try { await anotarFalha($, 'conclusão de tarefa', motivo) } catch { $.ui.status('portão: falhou na conclusão de tarefa') }
    const ids = idsNoAssunto(e.task_subject)
    const tarefa = quadro?.tarefas[String(e.task_id)] ?? (ids.length === 1 ? ids[0] : undefined)
    if (!tarefa) return next(e)
    return { block: textoDoBloqueio(tarefa, { tipo: 'indisponivel', motivo: `o Portão falhou ao conferir: ${motivo}` }) }
  })

  // O teammate ocioso (T10.3): com os tetos do piloto na sessão, quem ficou ocioso sem concluir devolve a tarefa, e a
  // próxima tarefa livre do plano (D7) vai a ele pelo `block`. Livre é sem lease `path:` ativo de nenhuma thread na
  // região e sem cruzar as tarefas dos outros teammates (D8 revista); a escolha e a atribuição acontecem juntas sobre o
  // quadro mais novo. No teto de custo, sem os leases legíveis ou sem tarefa livre, o teammate fica ocioso.
  on('classic.TeammateIdle', async ($, e, next) => {
    const sessao = await sessaoDoPortao($)
    if (!sessao || !sessao.tarefas) return next(e)
    const tetos = await lerTetos($)
    const teammate = nomeDoTeammate(e.teammate_name)
    if (!tetos || !teammate) return next(e)
    const { ctx, tarefas } = sessao
    await mudarQuadro($, ctx.thread, q => {
      const tinha = q.atribuicoes[teammate]
      if (!tinha) return q
      const atribuicoes = { ...q.atribuicoes }
      delete atribuicoes[teammate]
      const devolvida = !q.concluidas.includes(tinha) && !q.devolvidas.includes(tinha)
      return { ...q, atribuicoes, devolvidas: devolvida ? [...q.devolvidas, tinha] : q.devolvidas }
    })
    const custo = await custoDaSessao($)
    if (custo === null || custo >= tetos.custoUsd) {
      $.ui.status(custo === null ? 'portão: custo da sessão ilegível; nenhuma tarefa nova ao time' : `portão: teto de custo do piloto (US$ ${tetos.custoUsd}) atingido`)
      return next(e)
    }
    let leases: LeaseAtivo[]
    try {
      leases = await lerLeases($)
    } catch (erro) {
      await anotarFalha($, 'leitura dos leases', erro, ctx.thread)
      return next(e)
    }
    let entregue: PortaoTarefa | null = null
    await mudarQuadro($, ctx.thread, q => {
      const escolha = escolherTarefa({ tarefas, quadro: q, teammate, leases })
      if (!escolha) return q
      entregue = escolha
      return { ...q, atribuicoes: { ...q.atribuicoes, [teammate]: escolha.id } }
    })
    const tarefa = entregue as PortaoTarefa | null
    if (!tarefa) return next(e)
    $.ui.status(`portão: ${tarefa.id} com ${teammate}`)
    return { block: textoDaEntrega(tarefa, teammate) }
  }).catch(async ($, e, next) => {
    if (next.error && next.error.kind !== 're-entry') await anotarFalha($, 'teammate ocioso', next.error.message ?? next.error.kind)
    return next(e)
  })

  // Os tetos do piloto (D10): em toda sessão de fase, o teammate só nasce com os tetos do núcleo, abaixo do teto de
  // teammates vivos e do teto de custo. Subagente que não é teammate passa.
  on('agent.spawn', async ($, e, next) => {
    if (!e.isTeammate) return next(e)
    const ctx = await contextoDeFase($)
    if (!ctx) return next(e)
    const tetos = await lerTetos($)
    const vivos = (await $.agent.list()).filter(a => a.teammateId && VIVOS.includes(a.status)).length
    const recusa = recusaDoTeammate(tetos, vivos, tetos ? await custoDaSessao($) : null)
    if (recusa) {
      $.ui.status('portão: teammate recusado pelo teto do piloto')
      return { deny: recusa }
    }
    return next(e)
  }).catch(async ($, e, next) => {
    if (!next.error || next.error.kind === 're-entry' || !e.isTeammate || next.called) return next(e)
    const motivo = next.error.message ?? next.error.kind
    try { await anotarFalha($, 'teto de teammates', motivo) } catch { $.ui.status('portão: falhou no teto de teammates') }
    return { deny: `Portão de Tarefas: teammate recusado. O Portão não conseguiu conferir os tetos do piloto (${motivo}).` }
  })
}

files.hooks/plano.ts:
// O plano da thread como o Portão de Tarefas o usa (RM-059, fatia F10, T10.1). Módulo puro: interpreta o que o
// `ork_artifact_read` devolve, acha as tarefas `T<id>` com os `touch_paths` e o verify de cada uma pela mesma regra
// do `ork claims conferir --tarefa` do núcleo, tira o id da tarefa do assunto da tarefa nativa, decide a criação e
// lê o escopo no retrato da ponte. As chamadas ao `$` ficam no register.ts; nada aqui lê `.orkastery/` do disco.
import type { PortaoTarefa } from '../types'

export const SERVIDOR = 'orkastery'
/**
 * A lista fechada de ferramentas MCP do Portão: só a leitura do plano. O `$.mcp.call` não pede permissão ao
 * dono, então o teste do núcleo confere pela AST que o mod só chama esta.
 */
export const FERRAMENTA_DO_PLANO = 'ork_artifact_read'
export const FERRAMENTAS_DO_PORTAO: readonly string[] = [FERRAMENTA_DO_PLANO]
/** O plano lido vale por este tempo; sem plano (ou com erro), a leitura se repete depois de pouco. */
export const IDADE_DO_PLANO_MS = 60000
export const IDADE_SEM_PLANO_MS = 5000
/** Quantas tarefas do plano a recusa lista ao modelo, e o teto do texto inteiro. */
export const TETO_DE_TAREFAS_NO_TEXTO = 12
export const TETO_DO_TEXTO = 4000

const ID_DE_THREAD = /^[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}$/
/** O cabeçalho de tarefa do núcleo (`verifyDaTarefa`): `##` a `######`, `T<id>`, e o resto da linha. */
const CABECALHO_DE_TAREFA = /^(#{2,6})\s+T(\d+(?:\.\d+)*)(?=[\s.:)]|$)(.*)$/
/** A linha de verify nos formatos que o núcleo aceita; o grupo 1 é o que vem depois do rótulo. */
const ROTULO_DE_VERIFY = /^\s*(?:[-*]\s+)?(?:\*\*verify:\*\*|\*\*verify\*\*\s*:|`verify`\s*:|verify\s*:)\s*(.*)$/i
/**
 * O rótulo de `touch_paths` nos formatos em uso nos planos (o da carga do Freio), também com a contagem entre parênteses
 * antes dos dois-pontos (`- touch_paths (4): ...`).
 */
const ROTULO_DE_TOUCH_PATHS = /^\s*(?:[-*+]\s+)?(?:\*\*touch_paths(?:\s*\([^)]*\))?:?\*\*\s*:?|`touch_paths`(?:\s*\([^)]*\))?\s*:|touch_paths(?:\s*\([^)]*\))?\s*:)\s*(.*)$/i
/** Trecho entre crases com cara de caminho: barra, ponto ou curinga. Identificador da prosa (`Modo`, `fast`) não conta. */
const CARA_DE_CAMINHO = /[/.*?]/
/** Linha que abre outro item de lista, cabeçalho ou cerca de código. */
const ABRE_BLOCO = /^\s*(?:[-*+]\s|\d+[.)]\s|#{1,6}\s|```|~~~)/
const TRECHO = /`([^`]+)`/g
/** O id de uma tarefa do plano como palavra própria no assunto (`T2.1 ...`, `[T3]`), nunca colado a letra. */
const ID_NO_ASSUNTO = /(?:^|[^A-Za-z0-9_])T(\d+(?:\.\d+)*)(?![A-Za-z0-9_]|\.\d)/g
/** As fases na ordem do núcleo, com o dígito que o slug do bloco usa (`DIGITO_DA_FASE`). */
const FASES = ['GOAL', 'PLAN', 'GO', 'CHECK', 'SHIP', 'MASTER'] as const

export class ErroDoPlano extends Error {}

/** Os argumentos da leitura do plano da thread do despacho. */
export function argsDoPlano(thread: string): Record<string, unknown> {
  if (!ID_DE_THREAD.test(thread)) throw new ErroDoPlano('ork-portao: id de thread inválido')
  return { threadId: thread, tipo: 'plan' }
}

/** O JSON do primeiro bloco de texto de um resultado MCP; resultado com erro vira exceção. */
export function jsonDoMcp(r: unknown, ferramenta: string): unknown {
  const resultado = r as { content?: ReadonlyArray<{ type?: string; text?: unknown }>; isError?: boolean } | null
  const texto = (resultado?.content ?? []).find(c => c?.type === 'text' && typeof c.text === 'string')?.text as string | undefined
  if (resultado?.isError) throw new ErroDoPlano(`ork-portao: ${ferramenta} respondeu com erro${texto ? `: ${texto.slice(0, 200)}` : ''}`)
  if (texto === undefined) throw new ErroDoPlano(`ork-portao: ${ferramenta} não devolveu texto`)
  try {
    return JSON.parse(texto)
  } catch {
    throw new ErroDoPlano(`ork-portao: ${ferramenta} devolveu texto que não é JSON`)
  }
}

/** O texto do plano que o `ork_artifact_read` devolve, ou `null` quando a thread ainda não tem plano. */
export function textoDoPlano(bruto: unknown): string | null {
  const documento = bruto as { conteudo?: unknown } | null
  if (!documento || typeof documento !== 'object') throw new ErroDoPlano('ork-portao: o plano lido não é objeto')
  return typeof documento.conteudo === 'string' ? documento.conteudo : null
}

/** Caminho relativo normalizado: barras para a frente, sem `./` na frente nem barra no fim. */
export function normalizar(caminho: string): string {
  return caminho.trim().replace(/\\/g, '/').replace(/^(?:\.\/)+/, '').replace(/\/+$/, '')
}

function ehCaminho(texto: string): boolean {
  return texto !== '' && !/\s/.test(texto) && !texto.startsWith('-') && !texto.split('/').includes('..')
}

const recuo = (linha: string) => (/^[ \t]*/.exec(linha)?.[0] ?? '').replace(/\t/g, '    ').length

/**
 * O item inteiro do verify da linha `k` (a regra de `itemDoVerify` do núcleo): o texto depois do rótulo, a
 * continuação logo abaixo que não abre outro item e as linhas mais recuadas que o rótulo, mesmo depois de branco.
 */
function itemDoVerify(bloco: readonly string[], k: number, inicio: string): string {
  const base = recuo(bloco[k] as string)
  const partes = [inicio]
  let depoisDeBranco = false
  for (const linha of bloco.slice(k + 1)) {
    if (!linha.trim()) { depoisDeBranco = true; continue }
    if (recuo(linha) <= base && (depoisDeBranco || ABRE_BLOCO.test(linha))) break
    partes.push(linha.trim())
    depoisDeBranco = false
  }
  return partes.join(' ').trim()
}

/** O verify de uma tarefa pela regra do núcleo: o comando, ou o motivo com que o `ork claims conferir` recusaria. */
function verifyDoBloco(bloco: readonly string[]): { verify: string | null; problema: PortaoTarefa['problema'] } {
  const verifies = bloco.flatMap((l, k) => {
    const m = ROTULO_DE_VERIFY.exec(l)
    return m ? [itemDoVerify(bloco, k, (m[1] as string).trim())] : []
  })
  if (verifies.length === 0) return { verify: null, problema: 'tarefa-sem-verify' }
  if (verifies.length > 1) return { verify: null, problema: 'tarefa-ambigua' }
  const resto = verifies[0] as string
  if ([...resto.matchAll(TRECHO)].length === 0) return { verify: null, problema: 'tarefa-sem-comando' }
  const unico = /^`([^`]+)`\s*\.?$/.exec(resto)
  if (!unico || !(unico[1] as string).trim()) return { verify: null, problema: 'tarefa-ambigua' }
  return { verify: (unico[1] as string).trim(), problema: null }
}

/** Os `touch_paths` de uma tarefa: os trechos entre crases do item do rótulo e das linhas que o continuam. */
function touchPathsDoBloco(bloco: readonly string[]): string[] {
  const achados: string[] = []
  const juntar = (texto: string) => {
    for (const m of texto.matchAll(TRECHO)) {
      const bruto = (m[1] as string).trim()
      if (!CARA_DE_CAMINHO.test(bruto)) continue
      const caminho = normalizar(bruto)
      if (ehCaminho(caminho) && !achados.includes(caminho)) achados.push(caminho)
    }
  }
  let recuoDoRotulo = -1
  let depoisDeBranco = false
  for (const linha of bloco) {
    const r = recuo(linha)
    const rotulo = ROTULO_DE_TOUCH_PATHS.exec(linha)
    if (rotulo) {
      juntar(rotulo[1] as string)
      recuoDoRotulo = r
      depoisDeBranco = false
      continue
    }
    if (recuoDoRotulo < 0) continue
    if (linha.trim() === '') { depoisDeBranco = true; continue }
    if (r <= recuoDoRotulo && (depoisDeBranco || ABRE_BLOCO.test(linha))) { recuoDoRotulo = -1; continue }
    juntar(linha)
    depoisDeBranco = false
  }
  return achados
}

/**
 * As tarefas do plano, na ordem do texto (D3 do plano da thread): o cabeçalho `##` a `######` com `T<id>`, o bloco
 * até o próximo cabeçalho de nível igual ou maior, os `touch_paths` e o verify pela regra do núcleo. Id repetido
 * fica uma vez só, com o problema `tarefa-repetida`. `null` sem plano.
 */
export function tarefasDoPlano(conteudo: string | null): PortaoTarefa[] | null {
  if (typeof conteudo !== 'string') return null
  const linhas = conteudo.replace(/\r\n/g, '\n').split('\n')
  const inicios = linhas.flatMap((l, i) => {
    const m = CABECALHO_DE_TAREFA.exec(l)
    return m ? [{ i, nivel: (m[1] as string).length, id: `T${m[2] as string}`, titulo: (m[3] as string).replace(/^[\s.:)-]+/, '').trim() }] : []
  })
  const vistos = new Map<string, number>()
  for (const c of inicios) vistos.set(c.id, (vistos.get(c.id) ?? 0) + 1)
  const tarefas: PortaoTarefa[] = []
  for (const c of inicios) {
    if (tarefas.some(t => t.id === c.id)) continue
    const fim = linhas.findIndex((l, j) => j > c.i && new RegExp(`^#{1,${c.nivel}}\\s`).test(l))
    const bloco = linhas.slice(c.i + 1, fim < 0 ? undefined : fim)
    const { verify, problema } = (vistos.get(c.id) ?? 0) > 1 ? { verify: null, problema: 'tarefa-repetida' as const } : verifyDoBloco(bloco)
    tarefas.push({ id: c.id, titulo: c.titulo.slice(0, 120), touchPaths: touchPathsDoBloco(bloco), verify, problema })
  }
  return tarefas
}

/** Os ids distintos de tarefa do plano que o assunto da tarefa nativa cita, na ordem. */
export function idsNoAssunto(assunto: unknown): string[] {
  if (typeof assunto !== 'string') return []
  const ids: string[] = []
  for (const m of assunto.matchAll(ID_NO_ASSUNTO)) {
    const id = `T${m[1] as string}`
    if (!ids.includes(id)) ids.push(id)
  }
  return ids
}

/** A tarefa serve para o quadro: tem `touch_paths` e um verify que o núcleo confere. */
export function serveAoQuadro(t: PortaoTarefa): boolean {
  return t.touchPaths.length > 0 && t.verify !== null && t.problema === null
}

/** Por que a criação foi recusada (D2 e D3 do plano da thread). */
export type MotivoDaRecusa = 'sem-id' | 'ambigua' | 'fora-do-plano' | 'repetida' | 'sem-touch-paths' | 'sem-verify'

export type VereditoDaCriacao =
  | { tipo: 'passa'; tarefa: string }
  | { tipo: 'recusa'; motivo: MotivoDaRecusa; ids: string[]; tarefa: PortaoTarefa | null }

/** A criação de uma tarefa nativa contra as tarefas do plano. */
export function decidirCriacao(assunto: unknown, tarefas: readonly PortaoTarefa[]): VereditoDaCriacao {
  const ids = idsNoAssunto(assunto)
  if (ids.length === 0) return { tipo: 'recusa', motivo: 'sem-id', ids, tarefa: null }
  if (ids.length > 1) return { tipo: 'recusa', motivo: 'ambigua', ids, tarefa: null }
  const tarefa = tarefas.find(t => t.id === ids[0]) ?? null
  if (!tarefa) return { tipo: 'recusa', motivo: 'fora-do-plano', ids, tarefa: null }
  if (tarefa.problema === 'tarefa-repetida') return { tipo: 'recusa', motivo: 'repetida', ids, tarefa }
  if (tarefa.touchPaths.length === 0) return { tipo: 'recusa', motivo: 'sem-touch-paths', ids, tarefa }
  if (!serveAoQuadro(tarefa)) return { tipo: 'recusa', motivo: 'sem-verify', ids, tarefa }
  return { tipo: 'passa', tarefa: tarefa.id }
}

const DETALHE_DO_VERIFY: Record<string, string> = {
  'tarefa-sem-verify': 'não há linha de verify',
  'tarefa-sem-comando': 'o verify não tem comando entre crases',
  'tarefa-ambigua': 'o verify tem mais de uma linha, mais de um comando ou texto além do comando',
}

function motivoEmTexto(v: Extract<VereditoDaCriacao, { tipo: 'recusa' }>): string {
  const id = v.ids[0] ?? ''
  switch (v.motivo) {
    case 'sem-id': return 'o assunto não traz o id de uma tarefa do plano'
    case 'ambigua': return `o assunto cita mais de uma tarefa do plano (${v.ids.join(', ')}), e cada tarefa do quadro é uma tarefa do plano`
    case 'fora-do-plano': return `o plano não tem a tarefa ${id}`
    case 'repetida': return `o plano tem mais de um cabeçalho da tarefa ${id}`
    case 'sem-touch-paths': return `a tarefa ${id} do plano não tem touch_paths (caminhos entre crases, com barra, ponto ou curinga), então ninguém sabe que arquivos ela toca`
    case 'sem-verify': return `a tarefa ${id} do plano não tem um verify que o núcleo confira (${DETALHE_DO_VERIFY[v.tarefa?.problema ?? ''] ?? 'sem comando'})`
  }
}

/** Uma tarefa do plano como a lista ao modelo: o id e o título. */
export function rotulo(t: PortaoTarefa): string {
  return t.titulo ? `${t.id} (${t.titulo})` : t.id
}

/** O texto do `block` da criação recusada: o motivo, a regra e as tarefas do plano que servem. */
export function textoDaRecusa(v: Extract<VereditoDaCriacao, { tipo: 'recusa' }>, assunto: unknown, tarefas: readonly PortaoTarefa[]): string {
  const nome = typeof assunto === 'string' ? assunto.trim().slice(0, 120) : ''
  const servem = tarefas.filter(serveAoQuadro)
  const partes = [
    `Portão de Tarefas: a tarefa "${nome}" não entrou no quadro: ${motivoEmTexto(v)}.`,
    'No GO desta thread, cada tarefa do quadro é uma tarefa do plano: o assunto leva o id dela (por exemplo, "T2.1 título"), ' +
      'e a tarefa do plano precisa de touch_paths e de um verify com um comando só entre crases, que o núcleo confere ' +
      'quando a tarefa fecha (ork claims conferir --tarefa).',
  ]
  if (servem.length === 0) partes.push('Nenhuma tarefa do plano serve hoje: o plano precisa de touch_paths e de verify nas tarefas antes de abrir o quadro.')
  else {
    const lista = servem.slice(0, TETO_DE_TAREFAS_NO_TEXTO).map(rotulo).join('; ')
    const mais = servem.length > TETO_DE_TAREFAS_NO_TEXTO ? `; e mais ${servem.length - TETO_DE_TAREFAS_NO_TEXTO}` : ''
    partes.push(`Tarefas do plano que servem: ${lista}${mais}.`)
  }
  return limitarTexto(partes.join('\n'))
}

/** Um texto ao modelo dentro do teto, com a marca de corte. */
export function limitarTexto(texto: string): string {
  return texto.length > TETO_DO_TEXTO ? `${texto.slice(0, TETO_DO_TEXTO - 40)}\n(texto cortado pelo Portão de Tarefas)` : texto
}

/**
 * O GO está no bloco pelo slug que o núcleo dá a ele (`slugDasFases`): `full` são todas as fases, o nome de uma
 * fase em minúsculas é ela só, e `f` seguido de dígitos são as fases desses dígitos. `null` quando o slug não diz.
 */
export function faseNoBloco(slug: unknown, fase: string = 'GO'): boolean | null {
  if (typeof slug !== 'string' || slug === '') return null
  if (slug === 'full') return true
  const so = FASES.find(f => f.toLowerCase() === slug)
  if (so) return so === fase
  if (!/^f[1-6]+$/.test(slug)) return null
  const digito = String(FASES.indexOf(fase as (typeof FASES)[number]) + 1)
  return slug.slice(1).includes(digito)
}

/** O status e o slug do bloco da thread no retrato `ork.maestro-snapshot/v1`; `null` no que ele não diz. */
export function threadNoRetrato(retrato: unknown, thread: string): { status: string | null; bloco: string | null } {
  const itens = (retrato as { sections?: { threads?: { items?: unknown } } } | null)?.sections?.threads?.items
  if (!Array.isArray(itens)) return { status: null, bloco: null }
  const item = itens.find(i => (i as { id?: unknown } | null)?.id === thread) as { status?: unknown; facts?: { block?: unknown } } | undefined
  return {
    status: typeof item?.status === 'string' ? item.status : null,
    bloco: typeof item?.facts?.block === 'string' ? item.facts.block : null,
  }
}

/** O que decide se o Portão age (D1). */
export type Escopo = { ativo: true; avisos: string[] } | { ativo: false; motivo: string }

/** A metade do escopo que o retrato decide, antes de ler o plano: sem retrato, conta como bloco com GO e aberta. */
export function escopoDoRetrato(retrato: { status: string | null; bloco: string | null } | null): Escopo {
  if (retrato === null) return { ativo: true, avisos: ['retrato indisponível; o Portão confere mesmo assim'] }
  if (retrato.status === 'fechada') return { ativo: false, motivo: 'thread fechada' }
  if (faseNoBloco(retrato.bloco) === false) return { ativo: false, motivo: `o bloco ${retrato.bloco} não tem o GO` }
  return { ativo: true, avisos: [] }
}

/**
 * A outra metade (D1 refinada): o plano legível com ao menos uma tarefa que serve ao quadro. Plano em que nenhuma tarefa
 * tem `touch_paths` e verify conferível não ganha portão: travaria o quadro inteiro do GO.
 */
export function escopoDoPlano(tarefas: readonly PortaoTarefa[] | null): Escopo {
  if (tarefas === null) return { ativo: false, motivo: 'a thread ainda não tem plano legível' }
  if (tarefas.length === 0) return { ativo: false, motivo: 'o plano não tem tarefas T<n>' }
  if (!tarefas.some(serveAoQuadro)) return { ativo: false, motivo: 'nenhuma tarefa do plano tem touch_paths e verify conferível' }
  return { ativo: true, avisos: [] }
}

/** O escopo inteiro, como o register.ts o compõe: o retrato primeiro, o plano depois. */
export function decidirEscopo(retrato: { status: string | null; bloco: string | null } | null, tarefas: readonly PortaoTarefa[] | null): Escopo {
  const doRetrato = escopoDoRetrato(retrato)
  if (!doRetrato.ativo) return doRetrato
  const doPlano = escopoDoPlano(tarefas)
  return doPlano.ativo ? doRetrato : doPlano
}

