// A conclusão pela conferência do núcleo (RM-059, fatia F10, T10.2). Módulo puro: monta o argv do
// `ork claims conferir --tarefa`, lê o JSON `ork.claims-conferencia/v1`, conta a repetição e escreve o texto do
// bloqueio. O Portão nunca roda o verify da tarefa: quem roda é o núcleo, no sandbox do verify (D12 do plano dos
// mods), e quem verifica de verdade continua sendo o `ork verify`.
import type { PortaoRepeticao } from '../types'

export const FORMATO_DA_CONFERENCIA = 'ork.claims-conferencia/v1'
/** O prazo total pedido ao núcleo, em segundos (D5 corrigida: cabe no teto de dez minutos do `$.process.run`). */
export const PRAZO_DA_CONFERENCIA_S = 540
/** O vigia do mod: o `$.process.run` mata o processo depois disto, e a conferência fica indisponível. */
export const VIGIA_DA_CONFERENCIA_MS = 600000
/** Da terceira conclusão seguida bloqueada pelo mesmo resultado em diante, o texto manda deixar a tarefa aberta (D6). */
export const REPETICOES_PARA_DEIXAR = 3
/** Tetos do fim da saída que vai ao modelo. */
export const TETO_DE_LINHAS_DA_SAIDA = 15
export const TETO_DE_CARACTERES_DA_SAIDA = 1500

const ID_DE_THREAD = /^[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}$/
const ID_DE_TAREFA = /^T\d+(?:\.\d+)*$/
/** A saída do CLI quando outra condução segura a thread. */
const SAIDA_DE_CONDUCAO = 3

/** O argv do `ork claims conferir` do verify de uma tarefa; o comando da tarefa fica com o núcleo. */
export function argvDaConferencia(thread: string, tarefa: string): string[] {
  if (!ID_DE_THREAD.test(thread)) throw new Error('ork-portao: id de thread inválido')
  if (!ID_DE_TAREFA.test(tarefa)) throw new Error('ork-portao: id de tarefa inválido')
  return ['ork', 'claims', 'conferir', thread, '--tarefa', tarefa, '--prazo', String(PRAZO_DA_CONFERENCIA_S), '--json']
}

/**
 * O que a conferência disse da tarefa: aprovada; reprovada (`claims.failed`); sem veredito (prazo, comando que não
 * rodou); recusada pelo núcleo (`claims.conferir.*`); com outra condução na thread; ou indisponível.
 */
export type Leitura =
  | { tipo: 'aprovada'; comando: string }
  | { tipo: 'reprovada'; comando: string; codigo: number | null; fim: string }
  | { tipo: 'sem-veredito'; motivo: string; comando: string; detalhe: string }
  | { tipo: 'recusada'; motivo: string }
  | { tipo: 'ocupada'; motivo: string }
  | { tipo: 'indisponivel'; motivo: string }

const ultimaLinha = (texto: string) => texto.trim().split('\n').filter(l => l.trim() !== '').slice(-1)[0]?.trim().slice(0, 300) ?? ''

type Execucao = { comando?: unknown; ok?: unknown; code?: unknown; fim?: unknown }

/**
 * A saída do `ork claims conferir --tarefa --json` (D4): o resultado só com o formato certo, o item da tarefa pedida
 * e a saída 0 ou 1; a recusa tipada é a saída 2 com `claims.conferir.*`; a saída 3 é outra condução; o resto (texto
 * solto de um `ork` antigo, JSON sem o item) é indisponível.
 */
export function lerConferencia(tarefa: string, stdout: string, codigo: number | null, stderr: string): Leitura {
  let j: { formato?: unknown; itens?: unknown; erro?: unknown; texto?: unknown } | null = null
  try { j = JSON.parse(stdout) } catch { j = null }
  if (j && j.formato === FORMATO_DA_CONFERENCIA && Array.isArray(j.itens) && (codigo === 0 || codigo === 1)) {
    const item = (j.itens as Array<{ id?: unknown; verificado?: unknown; motivo?: unknown; detalhe?: unknown; execucoes?: unknown } | null>)
      .find(i => i?.id === tarefa)
    if (!item) return { tipo: 'indisponivel', motivo: `a conferência não devolveu a tarefa ${tarefa}` }
    const execucoes = Array.isArray(item.execucoes) ? item.execucoes as Execucao[] : []
    const chave = execucoes.find(x => x && x.ok === false) ?? execucoes[0]
    const comando = typeof chave?.comando === 'string' ? chave.comando : ''
    if (item.verificado === true && codigo === 0) return { tipo: 'aprovada', comando }
    if (item.motivo === 'claims.failed') {
      return { tipo: 'reprovada', comando, codigo: typeof chave?.code === 'number' ? chave.code : null, fim: typeof chave?.fim === 'string' ? chave.fim : '' }
    }
    return {
      tipo: 'sem-veredito', comando,
      motivo: typeof item.motivo === 'string' ? item.motivo : 'sem motivo',
      detalhe: typeof item.detalhe === 'string' ? item.detalhe.slice(0, 300) : '',
    }
  }
  const erro = j && typeof j.erro === 'string' ? j.erro.trim().slice(0, 300) : ''
  if (codigo === SAIDA_DE_CONDUCAO) {
    // Com `--json`, a recusa de condução sai no stdout (`ork.conducao-recusa/v1`), com o texto para quem lê.
    const texto = j && typeof j.texto === 'string' ? (j.texto.trim().split('\n')[0] ?? '').slice(0, 300) : ''
    return { tipo: 'ocupada', motivo: texto || erro || ultimaLinha(stderr) || 'outra condução segura a thread' }
  }
  if (erro.startsWith('claims.conferir.')) return { tipo: 'recusada', motivo: erro }
  const motivo = erro || ultimaLinha(stderr) || (j === null ? ultimaLinha(stdout) : '') || `saiu com código ${codigo ?? 'desconhecido'}`
  return { tipo: 'indisponivel', motivo: `ork claims conferir sem resultado: ${motivo}` }
}

/** O fim da saída de um comando: as últimas linhas e o último trecho, dentro dos tetos. */
export function fimDaSaida(fim: string): string[] {
  let texto = fim.replace(/\s+$/, '')
  if (texto.length > TETO_DE_CARACTERES_DA_SAIDA) texto = texto.slice(-TETO_DE_CARACTERES_DA_SAIDA)
  return texto === '' ? [] : texto.split('\n').slice(-TETO_DE_LINHAS_DA_SAIDA)
}

/** O que torna dois bloqueios "o mesmo resultado" para a contagem da D6. */
export function assinatura(l: Leitura): string {
  switch (l.tipo) {
    case 'aprovada': return 'aprovada'
    case 'reprovada': return JSON.stringify(['reprovada', l.comando, l.codigo, fimDaSaida(l.fim).slice(-3)])
    case 'sem-veredito': return JSON.stringify(['sem-veredito', l.motivo, l.comando])
    default: return JSON.stringify([l.tipo, l.motivo])
  }
}

/** A repetição da tarefa depois deste bloqueio: a mesma assinatura soma, outra recomeça em 1. */
export function contarRepeticao(anterior: PortaoRepeticao | undefined, nova: string): PortaoRepeticao {
  return anterior && anterior.assinatura === nova ? { assinatura: nova, vezes: anterior.vezes + 1 } : { assinatura: nova, vezes: 1 }
}

const SAIDA = 'Se não der para corrigir agora, devolva a tarefa para pending (TaskUpdate) e siga: o ork verify continua sendo quem verifica.'

/** O texto do `block` da conclusão recusada (D4 e D6), com a saída sempre dita. */
export function textoDoBloqueio(tarefa: string, l: Exclude<Leitura, { tipo: 'aprovada' }>, vezes = 1): string {
  const partes: string[] = []
  switch (l.tipo) {
    case 'reprovada':
      partes.push(`Portão de Tarefas: a tarefa ${tarefa} não fecha: o verify do plano reprovou na conferência do núcleo (ork claims conferir, no sandbox do verify, sem recibo).`)
      if (l.comando) partes.push(`  comando: ${l.comando}`)
      partes.push(`  saiu com código ${l.codigo ?? 'desconhecido'}${l.fim.trim() ? '; fim da saída:' : ', sem saída'}`)
      for (const linha of fimDaSaida(l.fim)) partes.push(`  | ${linha}`)
      partes.push('Corrija e conclua de novo. Teste que cria processo pode reprovar no sandbox e passar no ork verify.')
      break
    case 'sem-veredito':
      partes.push(`Portão de Tarefas: a tarefa ${tarefa} não fecha: a conferência do núcleo terminou sem veredito (${l.motivo}${l.detalhe ? `: ${l.detalhe}` : ''}).`)
      if (l.comando) partes.push(`  comando: ${l.comando}`)
      partes.push('Conclua de novo para conferir outra vez.')
      break
    case 'recusada':
      partes.push(`Portão de Tarefas: a tarefa ${tarefa} não fecha: o núcleo recusou a conferência (${l.motivo}).`)
      break
    case 'ocupada':
      partes.push(`Portão de Tarefas: a tarefa ${tarefa} não fecha agora: outra condução segura a thread (${l.motivo}). Conclua de novo em instantes.`)
      break
    case 'indisponivel':
      partes.push(`Portão de Tarefas: a tarefa ${tarefa} não fecha: a conferência do núcleo não deu resultado (${l.motivo}).`)
      break
  }
  partes.push(SAIDA)
  if (vezes >= REPETICOES_PARA_DEIXAR) {
    partes.push(`É a ${vezes}ª vez seguida com o mesmo resultado: deixe a tarefa aberta (pending) e siga para a próxima; o ork verify do CHECK decide.`)
  }
  return partes.join('\n')
}

/** O texto do `block` quando outra conferência do Portão está em curso (D5). */
export function textoDeOutraConferencia(tarefa: string, emCurso: string): string {
  return `Portão de Tarefas: a tarefa ${tarefa} não fecha agora: o Portão está conferindo a tarefa ${emCurso} no núcleo, uma conferência por vez. ` +
    `Conclua de novo quando ela terminar. ${SAIDA}`
}

/** A linha de status depois de uma conferência; `undefined` limpa a linha. */
export function textoDoStatus(tarefa: string, l: Leitura): string | undefined {
  if (l.tipo === 'aprovada') return undefined
  const nome: Record<Exclude<Leitura['tipo'], 'aprovada'>, string> = {
    reprovada: 'reprovou', 'sem-veredito': 'sem veredito', recusada: 'recusada pelo núcleo', ocupada: 'outra condução', indisponivel: 'conferência indisponível',
  }
  return `portão: ${tarefa} não fechou (${nome[l.tipo]})`
}

files.hooks/lease.ts:
// O teammate ocioso e os leases (RM-059, fatia F10, T10.3). Módulo puro: a colisão de leases e de `touch_paths` pela
// regra do núcleo (`leasesColidem` e `globsColidem` de `core/src/leases.ts`, reimplementados aqui porque mod não
// importa código do núcleo, e cruzados no teste do núcleo), os leases ativos de todas as threads página a página do
// retrato do `ork maestro --json`, a escolha da próxima tarefa para o teammate, os tetos do piloto de agent teams e os
// textos. O Portão não toma nem solta lease (D8 revista): o `ork_git_commit` toma o `path:` de cada arquivo na hora do
// commit e recusa com qualquer lease no caminho, até da própria thread. As chamadas ao `$` ficam no register.ts.
import type { PortaoQuadro, PortaoTarefa } from '../types'

/** Os tetos do piloto (D10 do plano da thread), como o núcleo os passa no `env` do `--settings`. */
export const ENV_TEAMMATES = 'ORK_AGENT_TEAMS_TEAMMATES'
export const ENV_CUSTO = 'ORK_AGENT_TEAMS_CUSTO_USD'
export const TETO_MAXIMO_DE_TEAMMATES = 8
export const TETO_MAXIMO_DE_CUSTO_USD = 500
/**
 * Quantas páginas da seção `leases` o Portão lê numa vez. O retrato traz até 50 itens por página e corta a página pelo
 * teto de bytes do retrato inteiro (`maestro.page.byte_limit`), então uma página costuma vir com menos.
 */
export const TETO_DE_PAGINAS_DE_LEASES = 10
/** A lacuna que o núcleo põe na página cortada pelo teto de bytes: é paginação, com `nextOffset`, não falta de dado. */
export const LACUNA_DE_PAGINA = 'maestro.page.byte_limit'
/** Os estados de agente que contam como teammate vivo para o teto. */
export const VIVOS: readonly string[] = ['pending', 'running', 'waiting', 'idle']

const NOME_DE_TEAMMATE = /^[A-Za-z0-9][A-Za-z0-9._@-]{0,79}$/
const FAMILIAS = ['worktree-write', 'path', 'board', 'service', 'exec']

/** A família de um lease, como `tipoDoLease` do núcleo: prefixo conhecido, `main-tree`, ou `path` por padrão. */
export function familiaDoLease(nome: string): string {
  if (nome === 'main-tree') return 'main-tree'
  const prefixo = nome.split(':')[0] as string
  return FAMILIAS.includes(prefixo) ? prefixo : 'path'
}

/** O alvo de um lease (o que vem depois dos dois pontos), como `alvoDoLease` do núcleo. */
export function alvoDoLease(nome: string): string {
  const corte = nome.indexOf(':')
  return corte < 0 ? '' : nome.slice(corte + 1)
}

/** O glob de caminho (`*`, `**`, `?`) como a regex equivalente, como `globParaRegex` do núcleo. */
export function globParaRegex(glob: string): RegExp {
  let re = ''
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i] as string
    if (c === '*') {
      if (glob[i + 1] === '*') {
        re += '.*'
        i++
        if (glob[i + 1] === '/') i++
      } else {
        re += '[^/]*'
      }
    } else if (c === '?') {
      re += '[^/]'
    } else {
      re += c.replace(/[.+^${}()|[\]\\]/g, '\\$&')
    }
  }
  return new RegExp(`^${re}$`)
}

function prefixoLiteral(glob: string): string {
  const corte = glob.search(/[*?]/)
  return corte < 0 ? glob : glob.slice(0, corte)
}

function prefixoDeCaminho(a: string, b: string): boolean {
  if (a === '') return false
  if (!b.startsWith(a)) return false
  return a.length === b.length || a.endsWith('/') || b[a.length] === '/'
}

/** Dois globs disputam a mesma região? Conservador como o do núcleo: na dúvida, colide. */
export function globsColidem(a: string, b: string): boolean {
  if (a === b) return true
  if (globParaRegex(a).test(b) || globParaRegex(b).test(a)) return true
  const pa = prefixoLiteral(a)
  const pb = prefixoLiteral(b)
  return prefixoDeCaminho(pa, pb) || prefixoDeCaminho(pb, pa)
}

/** Dois nomes de lease colidem? Famílias diferentes nunca; `path` pela colisão de glob; o resto pela igualdade. */
export function leasesColidem(a: string, b: string): boolean {
  if (a === b) return true
  const fa = familiaDoLease(a)
  if (fa !== familiaDoLease(b)) return false
  return fa === 'path' ? globsColidem(alvoDoLease(a), alvoDoLease(b)) : false
}

/** O lease `path:` de um `touch_path` da tarefa. */
export function nomeDoLease(touchPath: string): string {
  return `path:${touchPath}`
}

/** Um lease ativo do retrato: o nome e a thread que o segura. */
export type LeaseAtivo = { nome: string; thread: string }

/** Os leases ativos de uma página da seção `leases` do retrato `ork.maestro-snapshot/v1`, de qualquer família. */
export function leasesDoRetrato(retrato: unknown): LeaseAtivo[] {
  const itens = (retrato as { sections?: { leases?: { items?: unknown } } } | null)?.sections?.leases?.items
  if (!Array.isArray(itens)) throw new Error('ork-portao: o retrato veio sem a seção leases')
  const ativos: LeaseAtivo[] = []
  for (const bruto of itens) {
    const item = bruto as { id?: unknown; status?: unknown; refs?: unknown } | null
    if (!item || typeof item.id !== 'string' || item.status !== 'active' || !Array.isArray(item.refs)) continue
    const ref = (item.refs as Array<{ kind?: unknown; id?: unknown } | null>).find(r => r?.kind === 'thread')
    if (ref && typeof ref.id === 'string') ativos.push({ nome: item.id, thread: ref.id })
  }
  return ativos
}

/** Uma página da seção `leases`: os ativos, o offset da página seguinte (`coverage.nextOffset`) e o que faltou. */
export type PaginaDeLeases = { leases: LeaseAtivo[]; proximo: number | null; lacuna: string | null }

/**
 * A página da seção `leases` de um retrato. Seção indisponível lança (sem ela, nenhuma região está livre). A página
 * cortada pelo teto de bytes (`maestro.page.byte_limit`) só diz que há página seguinte; qualquer outra lacuna, ou o
 * retrato em conflito (fontes mudando durante a leitura), deixa a leitura incompleta.
 */
export function paginaDosLeases(retrato: unknown): PaginaDeLeases {
  type Secao = { state?: unknown; gaps?: unknown; coverage?: { nextOffset?: unknown } }
  const secao = (retrato as { sections?: { leases?: Secao } } | null)?.sections?.leases
  if (!secao || typeof secao !== 'object') throw new Error('ork-portao: o retrato veio sem a seção leases')
  const faltas = Array.isArray(secao.gaps) ? secao.gaps.filter((g): g is string => typeof g === 'string') : []
  if (secao.state === 'unavailable') throw new Error(`ork-portao: a seção leases veio indisponível${faltas.length ? ` (${faltas.join(', ')})` : ''}`)
  const seguinte = secao.coverage?.nextOffset
  const proximo = typeof seguinte === 'number' && Number.isInteger(seguinte) && seguinte > 0 ? seguinte : null
  const outras = faltas.filter(g => g !== LACUNA_DE_PAGINA)
  const lacuna = secao.state === 'conflict' ? 'a seção leases veio em conflito (o retrato mudou durante a leitura)'
    : outras.length > 0 ? `a seção leases veio com lacunas (${outras.join(', ')})` : null
  return { leases: leasesDoRetrato(retrato), proximo, lacuna }
}

/** Os tetos do piloto lidos do ambiente: teammates inteiro de 1 a 8 e custo de 0 a 500 dólares; `null` sem os dois. */
export function tetosDoAmbiente(teammates: unknown, custo: unknown): { teammates: number; custoUsd: number } | null {
  if (typeof teammates !== 'string' || typeof custo !== 'string') return null
  const t = /^\d+$/.test(teammates.trim()) ? Number(teammates.trim()) : NaN
  const c = /^\d+(?:\.\d+)?$/.test(custo.trim()) ? Number(custo.trim()) : NaN
  if (!Number.isInteger(t) || t < 1 || t > TETO_MAXIMO_DE_TEAMMATES) return null
  if (!Number.isFinite(c) || c <= 0 || c > TETO_MAXIMO_DE_CUSTO_USD) return null
  return { teammates: t, custoUsd: c }
}

const dolares = (v: number) => `US$ ${v.toFixed(2)}`

/** Por que o `agent.spawn` de um teammate é recusado (D10); `null` quando ele passa. */
export function recusaDoTeammate(tetos: { teammates: number; custoUsd: number } | null, vivos: number, custo: number | null): string | null {
  if (!tetos) {
    return 'Portão de Tarefas: teammate recusado. Na sessão de fase, agent teams só rodam no piloto do núcleo, com os tetos de ' +
      `runtime.agent_teams no manifesto, e esta sessão não recebeu ${ENV_TEAMMATES} e ${ENV_CUSTO}.`
  }
  if (vivos >= tetos.teammates) return `Portão de Tarefas: teammate recusado. A sessão já tem ${vivos} teammate(s) vivo(s), e o teto do piloto é ${tetos.teammates}.`
  if (custo === null) return 'Portão de Tarefas: teammate recusado. O custo da sessão não pôde ser lido, e sem ele o teto de custo do piloto não vale.'
  if (custo >= tetos.custoUsd) return `Portão de Tarefas: teammate recusado. O custo da sessão (${dolares(custo)}) chegou ao teto do piloto (${dolares(tetos.custoUsd)}).`
  return null
}

/** O nome do teammate como o evento traz, conferido; `null` quando não serve. */
export function nomeDoTeammate(bruto: unknown): string | null {
  return typeof bruto === 'string' && NOME_DE_TEAMMATE.test(bruto) ? bruto : null
}

/**
 * A próxima tarefa para o teammate (D7 e D8 revista): na ordem do plano, a que serve ao quadro, não fechou, não foi
 * devolvida, não está com outro teammate, não cruza os `touch_paths` das tarefas com outros teammates e não cruza lease
 * `path:` ativo de nenhuma thread, a própria incluída, porque o `ork_git_commit` recusa o commit com qualquer lease no
 * caminho. Sem tarefa livre, `null`.
 */
export function escolherTarefa(entrada: {
  tarefas: readonly PortaoTarefa[]
  quadro: PortaoQuadro
  teammate: string
  leases: readonly LeaseAtivo[]
}): PortaoTarefa | null {
  const { tarefas, quadro, teammate, leases } = entrada
  const comOutros = Object.entries(quadro.atribuicoes)
    .filter(([quem, tarefa]) => quem !== teammate && !quadro.concluidas.includes(tarefa))
    .map(([, tarefa]) => tarefa)
  const regiaoDosOutros = tarefas.filter(t => comOutros.includes(t.id)).flatMap(t => t.touchPaths)
  for (const tarefa of tarefas) {
    const livre = tarefa.touchPaths.length > 0 && tarefa.verify !== null && tarefa.problema === null &&
      !quadro.concluidas.includes(tarefa.id) && !quadro.devolvidas.includes(tarefa.id) && !comOutros.includes(tarefa.id) &&
      !tarefa.touchPaths.some(tp => regiaoDosOutros.some(outro => globsColidem(tp, outro))) &&
      !tarefa.touchPaths.some(tp => leases.some(l => leasesColidem(nomeDoLease(tp), l.nome)))
    if (livre) return tarefa
  }
  return null
}

/** O texto do `block` que entrega a tarefa ao teammate ocioso (D7). */
export function textoDaEntrega(t: PortaoTarefa, teammate: string): string {
  return [
    `Portão de Tarefas: ${teammate}, pegue a tarefa ${t.id} do plano${t.titulo ? ` (${t.titulo})` : ''}.`,
    `  touch_paths: ${t.touchPaths.join(', ')}`,
    `  verify: ${t.verify ?? ''}`,
    'Antes de começar, confira o quadro (TaskList): se ela já está em andamento com outro dono, não a pegue e fique ocioso. ' +
      `Se ela não está no quadro, crie-a com o assunto começando por ${t.id}; marque-a em andamento com você como dono. ` +
      'Quando o Portão a escolheu, nenhum lease path: ativo cruzava essa região, e o commit pelo ork_git_commit toma o lease ' +
      'de cada arquivo na hora. Ela só fecha com o verify aprovado pela conferência do núcleo.',
  ].join('\n')
}

